import sys
from collections import defaultdict

peaks_path, blacklist_path = sys.argv[1:3]

def bed_rows(path, min_cols=3):
    with open(path, "rt") as fh:
        for line_no, line in enumerate(fh, 1):
            if not line.strip() or line.startswith(("#", "track", "browser")):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < min_cols:
                raise ValueError(f"{path}:{line_no}: expected at least {min_cols} columns")
            yield line_no, fields

centered = []
for line_no, fields in bed_rows(peaks_path, 10):
    chrom = fields[0]
    start = int(fields[1])
    summit_offset = int(fields[9])
    summit = start + summit_offset
    new_start = summit - 250
    new_end = summit + 250
    if new_start < 0:
        raise ValueError(f"{peaks_path}:{line_no}: centered interval starts below zero")
    if new_end - new_start != 500:
        raise AssertionError("centered interval width is not 500")
    centered.append((chrom, new_start, new_end))

if not centered:
    raise ValueError("peak dataset contains no intervals")

centered.sort(key=lambda x: (x[0], x[1], x[2]))
merged = []
for chrom, start, end in centered:
    if merged and chrom == merged[-1][0] and start <= merged[-1][2]:
        if end > merged[-1][2]:
            merged[-1] = (chrom, merged[-1][1], end)
    else:
        merged.append((chrom, start, end))

black_by_chrom = defaultdict(list)
for line_no, fields in bed_rows(blacklist_path, 3):
    chrom = fields[0]
    start = int(fields[1])
    end = int(fields[2])
    if end < start:
        raise ValueError(f"{blacklist_path}:{line_no}: end precedes start")
    black_by_chrom[chrom].append((start, end))
for chrom in black_by_chrom:
    black_by_chrom[chrom].sort()

final = []
removed = 0
for chrom, start, end in merged:
    overlaps = False
    for bstart, bend in black_by_chrom.get(chrom, ()):
        if bstart >= end:
            break
        if bend > start and bstart < end:
            overlaps = True
            break
    if overlaps:
        removed += 1
    else:
        final.append((chrom, start, end))

for i, (chrom, start, end) in enumerate(final):
    if start < 0 or end <= start:
        raise AssertionError("invalid final interval")
    if i and chrom == final[i-1][0] and start <= final[i-1][2]:
        raise AssertionError("final intervals are not strictly separated")
    for bstart, bend in black_by_chrom.get(chrom, ()):
        if bstart >= end:
            break
        if bend > start and bstart < end:
            raise AssertionError("blacklist overlap remains in final intervals")

total_bases = sum(end - start for _, start, end in final)
with open("final.bed", "wt") as out:
    for chrom, start, end in final:
        out.write(f"{chrom}\t{start}\t{end}\n")
with open("summary.txt", "wt") as out:
    out.write(f"input_intervals\t{len(centered)}\n")
    out.write(f"centered_width_min\t{min(e-s for _,s,e in centered)}\n")
    out.write(f"centered_width_max\t{max(e-s for _,s,e in centered)}\n")
    out.write(f"merged_intervals\t{len(merged)}\n")
    out.write(f"blacklist_excluded_intervals\t{removed}\n")
    out.write(f"final_intervals\t{len(final)}\n")
    out.write("remaining_blacklist_overlaps\t0\n")
    out.write(f"total_bases\t{total_bases}\n")
